/// Returns the first index whose cumulative weight exceeds `target`.
s32 func_ov003_020c3b30(u16* weights, s32 count, s32 target) {
    s32 i;
    s32 sum;

    sum = 0;
    i   = 0;
    if (count <= 0) {
        return (s32)weights;
    }
    for (;;) {
        sum += weights[i];
        if (target < sum) {
            return i;
        }
        i++;
        if (i >= count) {
            return (s32)weights;
        }
    }
}

